logger = logging.getLogger("StandaloneLLMConversation")

@dataclass
class Message:
    role: str
    content: str
    timestamp: datetime = field(default_factory=datetime.now)
    metadata: Dict[str, Any] = field(default_factory=dict)

@dataclass
class Conversation:
    id: str
    title: str
    messages: List[Message] = field(default_factory=list)
    created_at: datetime = field(default_factory=datetime.now)
    updated_at: datetime = field(default_factory=datetime.now)
    provider: str = "fallback"
    model: str = "fallback"
    temperature: float = 0.3
    max_tokens: int = 1500
    system_prompt: Optional[str] = None
    metadata: Dict[str, Any] = field(default_factory=dict)

    def add_message(self, role: str, content: str, metadata: Optional[Dict[str, Any]] = None) -> None:
        self.messages.append(Message(role=role, content=content, metadata=metadata or {}))
        self.updated_at = datetime.now()

class LLMProviderBase(ABC):
    def __init__(self, name: str) -> None:
        self.name = name
        self.available = False

    @abstractmethod
    def generate(self, prompt: str, **kwargs: Any) -> Optional[str]:
        raise NotImplementedError

    @abstractmethod
    def generate_stream(self, prompt: str, **kwargs: Any) -> Iterator[str]:
        raise NotImplementedError

class OpenAIProvider(LLMProviderBase):
    def __init__(self) -> None:
        super().__init__("openai")
        self.client = None
        api_key = os.getenv("OPENAI_API_KEY", "")
        if api_key:
            try:
                from openai import OpenAI

                self.client = OpenAI(api_key=api_key)
                self.available = True
            except Exception:
                logger.exception("OpenAI init failed")

    def generate(self, prompt: str, **kwargs: Any) -> Optional[str]:
        if not self.available:
            return None
        try:
            resp = self.client.chat.completions.create(
                model=kwargs.get("model", "gpt-4o-mini"),
                messages=[{"role": "user", "content": prompt}],
                temperature=kwargs.get("temperature", 0.3),
                max_tokens=kwargs.get("max_tokens", 1500),
            )
            return resp.choices[0].message.content
        except Exception:
            logger.exception("OpenAI generate failed")
            return None

    def generate_stream(self, prompt: str, **kwargs: Any) -> Iterator[str]:
        if not self.available:
            return
        try:
            stream = self.client.chat.completions.create(
                model=kwargs.get("model", "gpt-4o-mini"),
                messages=[{"role": "user", "content": prompt}],
                temperature=kwargs.get("temperature", 0.3),
                max_tokens=kwargs.get("max_tokens", 1500),
                stream=True,
            )
            for chunk in stream:
                token = chunk.choices[0].delta.content
                if token:
                    yield token
        except Exception:
            logger.exception("OpenAI stream failed")

